                         o + 24, 0, o + 28, 0, o + 32, 0, o + 36, 0, o + 40, R.WEIGHT, o + 44, 0, o, pair.key)
                    changes[#changes + 1] = {address = slot, key = pair.key}
                    added = added + 1
