function M.new(api, game, natives, status, note)
    local self = {}
    local ffi = require('ffi')
    local menu_cache, screen_cache = 0, 0
    local prepared = nil            -- {action, title, body} the hidden dialog holds
    local pending = nil             -- action whose dialog is open
    local release = false           -- our text is on the dialog; clear it once hidden
    local last_answered = 0
    local refused = false           -- a write was refused: no retry until the menu opens again
    local labels = {}               -- button index -> text our button there shows
    local texts, text_addresses = {}, {}

    -- Text buffers live as long as the addon: a widget may still point at one
    -- after the screen that showed it is gone.
    local function text_address(text)
        local address = text_addresses[text]
        if not address then
            local buffer = ffi.new('char[?]', #text + 1, text)
            texts[text] = buffer
            address = tonumber(ffi.cast('uintptr_t', buffer))
            text_addresses[text] = address
        end
        return address
    end

    local function show_text(widget, text)
        local kind = math.floor(api.load32(widget) / 262144) % 16
        if kind == M.KIND_WRAPPED then
            natives.set_label_wrapped(widget, M.TEXT_TEMPLATE)
        else
            natives.set_label(widget, M.TEXT_TEMPLATE)
        end
        natives.set_string_arg(widget, M.TEXT_KEY, text_address(text))
    end

    -- The width a button's text may use: the button's width less the text's
    -- inset on both sides, so longer text scrolls inside the button.
    local function text_limit(button)
        local width = api.loadf(button + M.WIDGET_WIDTH) - 2 * api.loadf(button + M.BUTTON_TEXT + M.WIDGET_X)
        if width ~= width or width < 64 or width > 4096 then return M.TEXT_LIMIT end
        return width
    end

    -- Writes bytes {offset, value, ...} relative to a 4-aligned base with one
    -- page check: the words holding them are read, changed and written back
    -- (main thread only, like every writer of these fields).
    local function put_bytes(base, changes)
        local words, first, last = {}, nil, nil
        for i = 1, #changes, 2 do
            local offset, value = changes[i], changes[i + 1]
            local word_offset = offset - offset % 4
            local word = words[word_offset] or api.load32(base + word_offset)
            local scale = 256 ^ (offset % 4)
            word = word + (value - math.floor(word / scale) % 256) * scale
            words[word_offset] = word
            first = math.min(first or word_offset, word_offset)
            last = math.max(last or word_offset, word_offset)
        end
        local flat = {}
        for word_offset, word in pairs(words) do
            flat[#flat + 1] = word_offset - first
            flat[#flat + 1] = word
        end
        return api.write_words(base + first, last - first + 4, flat)
    end

    -- The escape screen is closed: what it held is forgotten (the screen, a
    -- refused write, the dialog prepared, open or holding our text). The one
    -- close path, for screen() and the idle gate (closed) alike.
    local function forget_screen()
        screen_cache, refused, prepared, pending, release = 0, false, nil, nil, false
    end
    -- The menu system, or 0 (not there, or a new one not readable yet).
    local function menu_system()
        local menu = api.load64(game + M.MENU_SYSTEM_PTR)
        if menu == 0 or menu % 8 ~= 0 then return 0 end
        if menu ~= menu_cache then
            if not api.read64(menu + M.SCREEN) then return 0 end
            menu_cache = menu
        end
        return menu
    end
    -- The open escape screen, or 0. The menu system and a new screen are each
    -- confirmed once with a guarded read; later frames use direct loads.
    local function open_screen()
        local menu = menu_system()
        if menu == 0 then return 0 end
        local screen = api.load64(menu + M.SCREEN)
        if screen == 0 or screen % 8 ~= 0 then forget_screen(); return 0 end
        if screen ~= screen_cache then
            if not api.read32(screen + M.SHOWN) or not api.read32(screen + M.CONTENT + M.COUNT) then return 0 end
            screen_cache, prepared, pending, release, labels, last_answered = screen, nil, nil, false, {}, 0
            refused = false
        end
        return screen
    end

    -- Port: true when every menu native can be called now (a stub whose entry
    -- checks out is replaced by the native; see G.checked_native).
    local function natives_ready()
        for name, native in pairs(natives) do
            if type(native) == 'table' then
                if not native.resolve() then return false end
                natives[name] = native.fn
            end
        end
        return true
    end

    local ACTION_TYPES = {}
    for index, action in ipairs(M.ACTIONS) do ACTION_TYPES[action] = M.FIRST_TYPE + index - 1 end
    local function our_action(type_byte)
        return M.ACTIONS[type_byte - M.FIRST_TYPE + 1]
    end

    -- Adds the offered actions that are missing (one checked write for all of
    -- them), relabels ours when their text changed, and has the game rebuild
    -- the list when one of ours is no longer offered. offer: action -> label;
    -- order: action names in priority order. Returns false when the write was
    -- refused.
    local function sync_buttons(content, offer, order)
        local count = api.load8(content + M.COUNT)
        if count > M.MAX_BUTTONS then return true end
        local present = {}
        for i = 0, count - 1 do
            local action = our_action(api.load8(content + M.TYPES + i))
            if action then
                if not offer[action] then
                    natives.rebuild(content, 0)
                    labels = {}
                    note('menu: buttons rebuilt (' .. action .. ' no longer offered)')
                    return true
                end
                present[action] = i
            end
        end
        local added, changes = nil, nil
        for _, action in ipairs(order) do
            if offer[action] and not present[action] and count < M.MAX_BUTTONS then
                changes, added = changes or {}, added or {}
                changes[#changes + 1] = 1 + count
                changes[#changes + 1] = ACTION_TYPES[action]
                present[action] = count
                added[#added + 1] = count
                count = count + 1
            end
        end
        if changes then
            if refused then return false end
            changes[#changes + 1] = 0
            changes[#changes + 1] = count
            if not put_bytes(content + M.COUNT, changes) then
                refused = true
                note('menu: button write refused; retried when the menu opens again')
                return false
            end
            for _, index in ipairs(added) do
                local button = content + M.BUTTONS + index * M.BUTTON_SIZE
                natives.add_child(content + M.BUTTON_LIST, button)
                labels[index] = nil
                natives.set_enabled(button, 1)
            end
        end
        for action, index in pairs(present) do
            local text = offer[action]
            if labels[index] ~= text then
                local button = content + M.BUTTONS + index * M.BUTTON_SIZE
                show_text(button + M.BUTTON_TEXT, text)
                natives.set_marquee(button + M.BUTTON_TEXT, text_limit(button))
                labels[index] = text
            end
        end
        return true
    end

    -- Puts an action's title and body on the dialog. Allowed at any time (a
    -- label change, not the queued setup).
    local function retext(content, dialog_text)
        local dialog = content + M.DIALOG
        show_text(dialog + M.DIALOG_TITLE, dialog_text.title)
        show_text(dialog + M.DIALOG_BODY, dialog_text.body)
        natives.measure_text(dialog + M.DIALOG_TITLE)
        natives.measure_text(dialog + M.DIALOG_BODY)
        release = true
    end

    -- Sets the hidden dialog up as the game does before its own dialogs (the
    -- confirm and cancel labels and the hold-to-confirm are the game's), with
    -- the action's title and body. Only while the dialog is idle: the setup
    -- queues otherwise.
    local function prepare(content, dialog_text)
        natives.dialog_setup(content + M.DIALOG, M.TEXT_TEMPLATE, M.TEXT_TEMPLATE, M.CONFIRM_LABEL, M.CANCEL_LABEL, 1, 0)
        retext(content, dialog_text)
    end

    -- Takes our text off the hidden dialog, so no COUNT argument of ours stays
    -- on a native dialog.
    local function release_dialog(content)
        local dialog = content + M.DIALOG
        natives.clear_args(dialog + M.DIALOG_TITLE + M.LABEL)
        natives.clear_args(dialog + M.DIALOG_BODY + M.LABEL)
        release, prepared = false, nil
    end

    -- The addon's fresh start (a pause after an error below it): the dialog in
    -- progress is forgotten, so an answer given meanwhile runs nothing, and the
    -- focus sets the dialog up again. Our buttons and texts stay as they are.
    function self.reset()
        prepared, pending, last_answered = nil, nil, 0
    end

    -- The open escape screen, or 0 (two direct loads while the menu is closed).
    function self.screen()
        local screen = open_screen()
        if screen == 0 then prepared, pending, release = nil, nil, false end
        return screen
    end

    -- The addon's idle gate: true while the escape screen is closed, which
    -- goes through forget_screen, the path a host closing the menu has always
    -- taken through screen(). An open screen, or a menu system that is not
    -- there or not confirmed readable, is left to the full frame untouched.
    -- Idle: two direct loads, no call into Windows. The menu system is
    -- confirmed once (one guarded read); a confirm that fails is tried again
    -- on every M.CONFIRM_RETRY-th call, not every frame.
    local confirm_wait = 0
    function self.closed()
        local menu = api.load64(game + M.MENU_SYSTEM_PTR)
        if menu == 0 or menu % 8 ~= 0 then return false end
        if menu ~= menu_cache then
            if confirm_wait > 0 then confirm_wait = confirm_wait - 1; return false end
            if menu_system() == 0 then confirm_wait = M.CONFIRM_RETRY - 1; return false end
        end
        local screen = api.load64(menu + M.SCREEN)
        if screen ~= 0 and screen % 8 == 0 then return false end
        -- Only a screen seen open holds state (screen_cache 0: forgotten already).
        if screen_cache ~= 0 then forget_screen() end
        return true
    end

    -- One frame on an open escape screen while the host has a squad.
    -- offer/order: see sync_buttons; dialogs: action -> {title, body};
    -- run(action) when its dialog is confirmed. Returns the peer (lo, hi) of
    -- the squad member whose player menu is open, or nil.
    function self.step(screen, local_lo, local_hi, offer, order, dialogs, run)
        local content = screen + M.CONTENT
        local selected_lo, selected_hi
        for i = 0, 3 do
            local card = content + M.CARDS + i * M.CARD_SIZE
            if api.load32(card + M.CARD_STATE) == M.POPUP_OPEN then
                local lo, hi = api.load32(card + M.CARD_PEER), api.load32(card + M.CARD_PEER + 4)
                if (lo ~= 0 or hi ~= 0) and not (lo == local_lo and hi == local_hi) then
                    selected_lo, selected_hi = lo, hi
                end
            end
        end
        if api.load32(screen + M.SHOWN) ~= 0 or api.load8(content + M.HIDDEN) ~= 0 then
            return selected_lo, selected_hi
        end
        if not natives_ready() then return selected_lo, selected_hi end
        if not sync_buttons(content, offer, order) then
            status.menu = 'write refused'
            return selected_lo, selected_hi
        end

        local count = api.load8(content + M.COUNT)
        local focus = api.load8(content + M.FOCUS)
        local action = nil
        if focus >= 4 and focus - 4 < count then action = our_action(api.load8(content + M.TYPES + focus - 4)) end
        local inactive = api.load8(content + M.DIALOG_INACTIVE) ~= 0
        -- The answer first: the game hides the dialog in the very frame it is
        -- answered (0x13FB1A0), so it is already inactive by now.
        if pending then
            local answered = api.load8(content + M.DIALOG_ANSWERED)
            if answered ~= 0 and last_answered == 0 then
                local confirmed = api.load8(content + M.DIALOG_CONFIRMED) ~= 0
                local done = pending
                pending = nil
                note('menu: ' .. done .. (confirmed and ' confirmed' or ' cancelled'))
                if confirmed then run(done) end
            elseif inactive then
                pending = nil -- closed without an answer
            else
                last_answered = answered
            end
        end
        local dialog_text = action and dialogs[action]
        local same = dialog_text and prepared and prepared.action == action and prepared.title == dialog_text.title
            and prepared.body == dialog_text.body
        if inactive then
            if dialog_text then
                -- Our button has the focus: set the hidden dialog up for it. While
                -- it is still fading out the setup would queue, so only the text
                -- changes then; the full setup follows once it is idle.
                if api.load32(content + M.DIALOG + M.DIALOG_STATE) == 0 then
                    if not (same and prepared.full) then
                        prepare(content, dialog_text)
                        prepared = {action = action, title = dialog_text.title, body = dialog_text.body, full = true}
                    end
                elseif not same then
                    retext(content, dialog_text)
                    prepared = {action = action, title = dialog_text.title, body = dialog_text.body, full = false}
                end
            elseif release then
                release_dialog(content)
            end
        elseif not pending and dialog_text then
            -- The game opened the dialog from our button: make sure it shows this
            -- button's title and body, whatever was prepared before.
            if not same then
                retext(content, dialog_text)
                prepared = {action = action, title = dialog_text.title, body = dialog_text.body, full = false}
            end
            pending, last_answered = action, api.load8(content + M.DIALOG_ANSWERED)
        end
        return selected_lo, selected_hi
    end

    -- The player menu's own KICK for peer (lo, hi), as a click on their card
    -- and a completed hold would do: the game kicks in its next update of the
    -- tab, which follows the mod's update in the same frame. Returns
    -- 'started' and the card index, or why not now: 'menu closed', 'other
    -- tab', 'busy' (dialog or panel not taking input), 'no card', 'no player
    -- menu', 'refused' (the timer write).
    function self.game_kick(screen, lo, hi)
        if screen == 0 then return 'menu closed' end
        if not natives_ready() then return 'busy' end
        local content = screen + M.CONTENT
        if api.load32(screen + M.SHOWN) ~= 0 or api.load8(content + M.HIDDEN) ~= 0 then return 'other tab' end
        if api.load8(content + M.DIALOG_INACTIVE) == 0 or api.load8(content + M.DIALOG_OPENING) ~= 0
            or api.loadf(content + M.DIALOG_FADE) ~= 0 or api.load32(content + M.PANEL_STATE) ~= 2 then
            return 'busy'
        end
        for i = 0, 3 do
            local card = content + M.CARDS + i * M.CARD_SIZE
            if api.load32(card + M.CARD_PEER) == lo and api.load32(card + M.CARD_PEER + 4) == hi then
                if api.load64(card + M.CARD_POPUP) == 0 then return 'no player menu' end
                natives.focus(content, i)
                natives.card_state(card, M.POPUP_OPEN)
                -- After opening: hiding a popup is what clears the timers.
                if not api.write_words(card + M.CARD_KICK_HOLD, 4, {0, M.KICK_HOLD_BITS}) then return 'refused' end
                return 'started', i
            end
        end
        return 'no card'
    end

    -- Closes the escape menu as Esc does. The squad moving to another ship
    -- while the menu was open left the old host's Helldiver in the menu pose
    -- (v0.4-diag7). Returns true, or false and why: 'closed' (not open),
    -- 'unreadable', 'refused' (the write).
    function self.close()
        local manager = api.load64(game + M.PRESENTERS_PTR)
        if manager == 0 then return false, 'closed' end
        local main = api.read64(manager + M.MAIN_PRESENTER)
        if not main then return false, 'unreadable' end
        if main == 0 then return false, 'closed' end
        if not api.read32(main + M.PENDING_CLOSE) then return false, 'unreadable' end
        if not put_bytes(main, {M.PENDING_CLOSE, 1}) then return false, 'refused' end
        return true
    end

    -- Diagnostic builds: the dialog and focus state, logged when it changes
    -- (to explain a confirm the mod did not see).
    local traced = nil
    function self.trace(screen)
        local text = 'closed'
        if screen ~= 0 then
            local content = screen + M.CONTENT
            local focus = api.load8(content + M.FOCUS)
            local count = api.load8(content + M.COUNT)
            text = string.format('tab %d hidden %d focus %d type %s dialog inactive %d opening %d answered %d '
                .. 'confirmed %d state %d fading %d panel %d pending %s prepared %s', api.load32(screen + M.SHOWN),
                api.load8(content + M.HIDDEN), focus,
                (focus >= 4 and focus - 4 < count) and tostring(api.load8(content + M.TYPES + focus - 4)) or '-',
                api.load8(content + M.DIALOG_INACTIVE), api.load8(content + M.DIALOG_OPENING),
                api.load8(content + M.DIALOG_ANSWERED), api.load8(content + M.DIALOG_CONFIRMED),
                api.load32(content + M.DIALOG + M.DIALOG_STATE), api.loadf(content + M.DIALOG_FADE) ~= 0 and 1 or 0,
                api.load32(content + M.PANEL_STATE), tostring(pending), prepared and prepared.action or '-')
        end
        if text ~= traced then
            traced = text
            note('menu trace: ' .. text)
        end
    end

    -- Once per session: the code the layout above depends on.
    function self.verify(unchecked)
        for _, code in ipairs(M.CODE) do
            local seen = api.bytes(game + code.rva, #code.bytes)
            if seen and seen ~= code.bytes then return false, code.name .. ' changed' end
            if not seen and unchecked then unchecked[#unchecked + 1] = code.name end
        end
        return true
    end

    return self
end

return M
end)()
local C = (function()
-- Squad messages, two kinds, action frames only:
--
-- A chat line: one line of the game's own text chat, sent the way the chat box
-- sends what the host types. The chat box (game.dll 0x186025D) hands the
-- network context's chat (ctx + 0xC418) and the typed text to 0x1097560, which
-- packs the UTF-8 text into rpc_ingame_chat_message (0x9FDDB88E, one u32
-- array), sends it to every other peer the host has not muted and shows it in
-- the host's own chat. The message has no sender or type field: every client,
-- with or without the mod, shows it as "<host>: text". (The game sends no chat
-- through PlayFab Party; v0.4-diag6's Party text reached nobody.)
--
-- The new squad leader notice (test builds): rpc_from_host_notify_new_host
-- (0xB9E77C36, one u64 peer id), which a host that took over after a mission
-- migration sends to every peer (game.dll 0x108A2DC). A client accepts it only
-- from its current host (0xB925A0); it then shows the new leader in its HUD and
-- adds event 5 {peer} to the session's event ring, from which the chat shows
-- "<name> is the new squad leader" (no colon). Other clients also send the
-- named peer their migration state (RPC 0xE15F07B2 per tracked object), so it
-- is tested with one friend first.
local C = {}

C.CHAT = 0xc418                -- network context -> the game's text chat; +0 enabled (byte)
C.SEND = {rva = 0xf27db0, type = 'LmChatSend', bytes =
        '\65\86\65\87\72\129\236\120\4\0\0\72\139\5\78\210\88\1\72\51\196\72\137\132\36\80\4\0\0\128\57\0'}
-- The game's RPC send: (hash, target peer or -1 for every other peer, arguments, count).
C.RPC = {rva = 0xbfcbd0, type = 'LmRpcSend', bytes =
        '\64\83\85\86\87\65\86\65\87\72\129\236\152\0\0\0\72\139\5\41\132\139\1\72\51\196\72\137'}
C.CODE = {
    -- The chat box hands the context's chat and the typed text to the send.
    {rva = 0x16e163d, name = 'chat box send', bytes =
        '\72\139\13\228\107\117\1\76\141\135\212\22\0\0\72\129\193\24\196\0\0\232\89\103\132\255'},
    -- The send's message: rpc_ingame_chat_message with one argument.
    {rva = 0xc09ac3, name = 'chat message RPC', bytes = nil},
    -- The chat's 64-line history (first line, line count), read by diagnostic builds.
    {rva = 0xf282cc, name = 'chat history', bytes =
        '\139\135\148\149\0\0\139\143\144\149\0\0'},
    -- The game's own new-host notice: one argument of type 9 (8 bytes), to every peer (-1).
    {rva = 0xf1aa8c, name = 'new host notice', bytes =
        '\72\141\69\103\72\137\93\103\65\185\1\0\0\0\72\137\69\231\76\141\69\223\199\69\223\9\0\0\0\72'
        .. '\199\194\255\255\255\255\199\69\227\8\0\0\0\185\54\124\231\185\232\15\33\206\255'},
}
C.HISTORY_FIRST, C.HISTORY_COUNT = 0x9590, 0x9594
C.MAX_TEXT = 512               -- the game sends at most 512 bytes and drops a line that is not valid UTF-8
C.NEW_HOST = 0xb9e77c36        -- rpc_from_host_notify_new_host
C.ARG_U64, C.ARG_U64_SIZE = 9, 8
C.EVERY_PEER = 0xffffffff      -- both halves of the target -1
-- One RPC argument: {u32 type, u32 size, u64 address of the value}; the value follows.
C.ARGS_SIZE, C.ARG_VALUE = 24, 16

-- text cut to at most max bytes without splitting a UTF-8 sequence.
function C.cut(text, max)
    if #text <= max then return text end
    local n = max
    while n > 0 and text:byte(n + 1) >= 0x80 and text:byte(n + 1) < 0xc0 do n = n - 1 end
    return text:sub(1, n)
end

-- game: the game.dll base. G: src/game.lua. note(message): the mod's log.
function C.new(api, game, G, note)
    local self = {}
    local send, rpc, text_buffer, args

    -- Once: the natives and the code that fixes the chat's place and the messages.
    function self.verify(unchecked)
        local why
        send, why = G.checked_native(api, C.SEND.type, game + C.SEND.rva, C.SEND.bytes, 'chat send')
        if not send then return false, why end
        rpc, why = G.checked_native(api, C.RPC.type, game + C.RPC.rva, C.RPC.bytes, 'RPC send')
        if not rpc then return false, why end
        for _, code in ipairs(C.CODE) do
            if not code.bytes then return false, code.name .. ': not known for this game build' end
            local matches = G.code_matches(api, game + code.rva, code.bytes)
            if matches == false then return false, code.name .. ' changed' end
            if matches == nil and unchecked then unchecked[#unchecked + 1] = code.name end
        end
        if unchecked and type(send) == 'table' then unchecked[#unchecked + 1] = 'chat send' end
        if unchecked and type(rpc) == 'table' then unchecked[#unchecked + 1] = 'RPC send' end
        text_buffer = api.buffer(C.MAX_TEXT + 1)
        args = api.buffer(C.ARGS_SIZE)
        api.put32(args, C.ARG_U64)
        api.put32(args + 4, C.ARG_U64_SIZE)
        api.put64(args + 8, args + C.ARG_VALUE)
        return true
    end

    local function history(chat)
        return api.load32(chat + C.HISTORY_FIRST) .. '/' .. api.load32(chat + C.HISTORY_COUNT)
    end

    -- The other players in the session: their count and, if verbose, their peer ids.
    local function others(ctx, verbose)
        local own_lo, own_hi = api.load32(ctx + G.LOCAL), api.load32(ctx + G.LOCAL + 4)
        local count, n, ids = math.min(api.load32(ctx + G.PEER_COUNT), G.MAX_PEERS), 0, verbose and {}
        for i = 0, count - 1 do
            local entry = ctx + G.PEERS + i * G.PEER_STRIDE
            local lo, hi = api.load32(entry), api.load32(entry + 4)
            if lo ~= own_lo or hi ~= own_hi then
                n = n + 1
                if ids then ids[#ids + 1] = string.format('%08X%08X', hi, lo) end
            end
        end
        return n, ids and table.concat(ids, ', ')
    end

    -- Sends text as the host's chat line. Returns true and the number of other
    -- players in the session, or false and why. verbose (diagnostic builds)
    -- logs the recipients' peer ids and the host's chat history before and
    -- after (a changed history means the game ran the whole send).
    function self.send(text, verbose)
        if not G.ready(send) then return false, 'the chat code is not loaded yet' end
        local ctx = api.load64(game + G.CONTEXT_PTR)
        if ctx == 0 then return false, 'no network session' end
        local chat = ctx + C.CHAT
        local enabled = api.read32(chat)
        if not enabled then return false, 'the chat is unreadable' end
        if enabled % 256 == 0 then return false, 'text chat is off' end
        local n, ids = others(ctx, verbose)
        if n == 0 then return false, 'nobody else in the session' end
        api.put_string(text_buffer, C.cut(text, C.MAX_TEXT), C.MAX_TEXT + 1)
        local before = verbose and history(chat)
        send(chat, 0, text_buffer)
        if verbose then
            note('squad message recipients: ' .. ids .. '; your chat history ' .. before .. ' -> ' .. history(chat))
        end
        return true, n
    end

    -- Tells every other player that the peer lo/hi is the new squad leader, as
    -- the game's own notice does. Returns true and the number of other players,
    -- or false and why. verbose (diagnostic builds) logs the recipients.
    function self.new_leader(lo, hi, verbose)
        if not G.ready(rpc) then return false, 'the RPC code is not loaded yet' end
        local ctx = api.load64(game + G.CONTEXT_PTR)
        if ctx == 0 then return false, 'no network session' end
        local n, ids = others(ctx, verbose)
        if n == 0 then return false, 'nobody else in the session' end
        api.put32(args + C.ARG_VALUE, lo)
        api.put32(args + C.ARG_VALUE + 4, hi)
        rpc(C.NEW_HOST, api.u64(C.EVERY_PEER, C.EVERY_PEER), args, 1)
        if verbose then note(string.format('squad leader notice for %08X%08X sent to %s', hi, lo, ids)) end
        return true, n
    end

    return self
end

return C
end)()
local S = (function()
-- Galactic Map lobby scanner recharge (Steam build 26088801 port), formerly the
-- standalone Fast Lobby Scanner.
--
-- The scanner copies the online config's recharge seconds into its countdown
-- each time a scan's results arrive (game.dll 0x1337fa8). This module keeps
-- that one config field at the player's setting, never above the game's own
-- value, and writes again whenever the game rewrites it (its online config
-- arrives at login and then about every 15 minutes).
local M = {}

M.CONFIG_PTR_RVA = 0x2e38218     -- online config object
M.RECHARGE = 0x3ceac             -- int32 seconds; read only by the scanner
M.MATCHMAKING_PTR_RVA = 0x2e381b8
M.COUNTDOWN = 0x10bd74           -- float seconds left ("SCANNER RECHARGING... N")
-- Settings: 5 s at the shortest, so the scanner's lobby searches never go
-- beyond one every ~5.3 s (5 s plus the search), about 4x the game's rate.
M.MIN_SECONDS, M.MAX_SECONDS, M.DEFAULT_SECONDS = 5, 20, 5
-- Game values outside this range are not treated as seconds. A game value
-- below the settings (a server that wants faster scans) is kept as it is.
M.GAME_VALUE_MIN, M.GAME_VALUE_LIMIT = 1, 3600
-- The game rewrites the field about every 15 minutes. Far more rewrites mean
-- something else keeps writing it; the mod then stops instead of paying a
-- page check every frame.
M.REWRITE_LIMIT = 500

-- Code this depends on, checked once per session before the first update.
M.CODE = {
    -- On entering "recharging": countdown = (float)[[game.dll+0x347cee0] + 0x3ce4c].
    {rva = 0x11cd238, name = 'recharge reader', bytes =
        '\72\139\5\217\175\198\1\69\139\206\102\15\110\128\172\206\3\0\139\134\40\167\0\0\199\134\60\189'
        .. '\16\0\50\0\0\0\137\134\64\241\12\0\137\134\216\242\12\0\15\91\192\243\15\17\134\116\189\16\0'},
    -- Every frame: if countdown > 0 then countdown -= dt.
    {rva = 0x11cc7be, name = 'countdown update', bytes =
        '\243\15\16\129\116\189\16\0\15\47\198\118\12\243\15\92\199\243\15\17\129\116\189\16\0'},
    -- A scanner setter: the matchmaking global holds the object with the
    -- scanner fields (+0x10bd5d here, the countdown at +0x10bd74).
    {rva = 0x11d3d30, name = 'matchmaking global', bytes =
        '\72\139\5\129\68\198\1\136\144\93\189\16\0\195'},
}

local function whole_seconds(value)
    if type(value) ~= 'number' or value ~= value then return nil end
    return math.max(M.MIN_SECONDS, math.min(M.MAX_SECONDS, math.floor(value + 0.5)))
end

local function plausible_pointer(value)
    return value >= 0x10000 and value < 0x800000000000 and value % 8 == 0
end

-- s: the table the addon keeps as its status; counts are kept there, and
-- s.revision changes whenever any of them does (one number to watch per frame).
function M.new(api, game, s)
    local self = {}
    s.status, s.writes, s.refreshes, s.shortened = 'waiting_for_config', 0, 0, 0
    s.setting, s.game_value, s.applied, s.revision = M.DEFAULT_SECONDS, nil, nil, 0
    local config_global, matchmaking_global = game + M.CONFIG_PTR_RVA, game + M.MATCHMAKING_PTR_RVA
    -- config: the object read32 confirmed, 0 while there is none; field: its
    -- recharge address. owner: the object settled and s.game_value describe.
    -- settled: the field value at which there is nothing to do. dirty: run
    -- the slow path next check.
    local config, field, owner, settled, dirty, stopped = 0, 0, 0, nil, false, false
    local function set_status(status)
        if s.status ~= status then s.status, s.revision = status, s.revision + 1 end
    end

    -- Shortens the running countdown to seconds when it is longer; a failure
    -- here only leaves one recharge at the old length.
    local function shorten(seconds)
        local matchmaking = api.load64(matchmaking_global)
        if not plausible_pointer(matchmaking) then return end
        local left = api.read_f32(matchmaking + M.COUNTDOWN)
        if not left or left ~= left or left <= seconds or left > M.GAME_VALUE_LIMIT then return end
        if api.write_f32(matchmaking + M.COUNTDOWN, seconds) then s.shortened = s.shortened + 1 end
    end

    -- The slow path: the field changed, the setting changed or the config
    -- object changed. Returns false after stopping. The revision moves for a
    -- new status or a new game value, not for the game rewriting its usual one.
    local function settle(current)
        dirty = false
        if current ~= settled then
            -- The game wrote the field, or this is the first look: its value.
            if settled ~= nil then
                s.refreshes = s.refreshes + 1
                if s.refreshes > M.REWRITE_LIMIT then
                    stopped = true
                    set_status('field_contended')
                    return false
                end
            end
            if current ~= s.game_value then s.game_value, s.revision = current, s.revision + 1 end
        end
        local game_value = s.game_value
        if game_value < M.GAME_VALUE_MIN or game_value > M.GAME_VALUE_LIMIT then
            -- 0: the object exists but the game has not filled it in yet (boot).
            settled, s.applied = current, nil
            set_status(game_value == 0 and 'waiting_for_game_value' or 'unexpected_game_value')
            return true
        end
        local seconds = math.min(s.setting, game_value)
        if seconds ~= current then
            if not api.write32(field, seconds) or api.load32(field) ~= seconds then
                stopped = true
                set_status('config_write_failed')
                return false
            end
            s.writes = s.writes + 1
            -- A scan result may already have used the old value this frame.
            if seconds < game_value then shorten(seconds) end
        end
        settled, s.applied = seconds, seconds
        set_status(seconds < game_value and 'active' or 'game_value_kept')
        return true
    end

    -- One check per frame. Idle (nothing changed): two direct loads.
    function self.check()
        if stopped then return false end
        local object = api.load64(config_global)
        if object ~= config or object == 0 then
            if object == 0 then
                config = 0
                set_status('waiting_for_config')
                return true
            end
            if not plausible_pointer(object) or not api.read32(object + M.RECHARGE) then
                -- Not confirmed readable: keep config at 0 and ask again next frame.
                config = 0
                set_status('waiting_for_config_read')
                return true
            end
            if object ~= owner then owner, settled, s.game_value, s.applied = object, nil, nil, nil end
            config, field, dirty = object, object + M.RECHARGE, true
        end
        local current = api.load32(field)
        if current == settled and not dirty then return true end
        return settle(current)
    end

    -- A setting from Mod Options Menu (or the default); the next check applies it.
    function self.set_setting(value)
        local seconds = whole_seconds(value)
        if not seconds then return false end
        if seconds ~= s.setting then s.setting, dirty, s.revision = seconds, true, s.revision + 1 end
        return true
    end

    -- Puts the game's value back while the field still holds this module's.
    -- Returns false only when that write failed.
    local function put_back()
        if config == 0 or config ~= owner or settled == nil or s.game_value == nil
            or settled == s.game_value then return true end
        if api.read32(field) ~= settled then return true end
        if not api.write32(field, s.game_value) then return false end
        settled = s.game_value -- the field holds the game's value now: not a rewrite
        return true
    end

    -- Stops checking and puts the game's value back when the field still
    -- holds this module's value. Returns false only when that write failed.
    function self.stop(reason)
        stopped, s.status, s.revision = true, reason or s.status, s.revision + 1
        return put_back()
    end

    -- The addon's pause after an error below it: the game's value goes back
    -- as on stop, and after resume() the next check confirms the object again
    -- and applies the setting (the counts stay). A stop stays a stop.
    local paused = false
    function self.pause(reason)
        if stopped then return true end
        paused = true
        return self.stop(reason)
    end
    function self.resume()
        if not paused then return false end
        paused, stopped, config, dirty = false, false, 0, true
        set_status('waiting_for_config')
        return true
    end

    return self
end

M.whole_seconds = whole_seconds
return M
end)()
local B = (function()
-- CANCEL SOS: stops the SOS Beacon the host called in, keeps it stopped, and
-- gives the SOS Beacon its use back so it can be called in again.
--
-- The game's SOS system (S) lists a mission for SOS joins. While its active
-- byte is set, the host's lobby carries the SOS flag (lobby key 8, PlayFab
-- number_key8, which SOS Quickplay searches for) and is forced Public (key 19,
-- number_key6), whatever the host's privacy setting. The game switches it off
-- only when the squad is full or the beacon is gone (0x67AA20: key 8 = 0), and
-- on again whenever a player leaves or a new host takes over while a beacon
-- stands (0xB5F140, 0x1087010). Its SOS off puts the privacy setting back
-- only when PlayFab already shows the SOS flag off, which it does not until
-- the lobby has posted; so the mod calls that same function, then sets key 19
-- to the privacy setting with the game's key setter, and lets the game post
-- both in this frame's update. It does the same after each re-arm, until the
-- mission ends or the host calls in a new beacon. The SOS Beacon stratagem has
-- one use per mission, which the cancelled beacon spent; the mod puts it back
-- in the host's own stratagem slot. Evidence: docs/TECHNICAL.md.
local B = {}

B.SOS_PTR = 0x2ce1db0           -- the SOS system
B.ACTIVE = 8                    -- byte: the SOS is on
B.ENABLED = 24                  -- u32: enabled SOS beacon components (the re-arms need one)
B.PRIVACY = 0xac5d0             -- game state -> the host's privacy setting
B.PRIVACY_NAMES = {[0] = 'Public', [1] = 'Friends Only', [2] = 'Invite Only', [3] = 'Friends and Clan'}
-- The game's lobby wrapper (network context + G.LOBBY): a cache of the lobby
-- keys as text, the keys the next post sends and the countdown to that post
-- (float seconds; the game posts at <= 0 and restarts it at 30 s).
